nextflow_workflow {

    name "Test Workflow BAM_MARKDUPLICATES_PICARD"
    script "../main.nf"
    workflow "BAM_MARKDUPLICATES_PICARD"
    config "./nextflow.config"

    tag "picard"
    tag "picard/markduplicates"
    tag "subworkflows"
    tag "subworkflows_nfcore"
    tag "bam_markduplicates_picard"
    tag "subworkflows/bam_markduplicates_picard"
    tag "subworkflows/bam_stats_samtools"
    tag "bam_stats_samtools"
    tag "samtools"
    tag "samtools/flagstat"
    tag "samtools/idxstats"
    tag "samtools/index"
    tag "samtools/stats"

    test("sarscov2 - bam") {

        when {
            workflow {
                """
                input[0] = Channel.of([
                    [ id:'test', single_end: false ], // meta map
                    file(params.modules_testdata_base_path + 'genomics/sarscov2/illumina/bam/test.paired_end.sorted.bam', checkIfExists: true)
                ])
                input[1] = Channel.of([
                    [ id:'genome' ],
                    file(params.modules_testdata_base_path + 'genomics/sarscov2/genome/genome.fasta', checkIfExists: true),
                    file(params.modules_testdata_base_path + 'genomics/sarscov2/genome/genome.fasta.fai', checkIfExists: true)
                ])
                """
            }
        }

        then {
            assertAll(
                { assert workflow.success},
                { assert path(workflow.out.metrics.get(0).get(1)).getText().contains("97") },
                { assert workflow.out.per_sample_mqc_bundle.size() == 1 },
                { assert workflow.out.per_sample_mqc_bundle[0][0] == [ id:'test', single_end: false ] },
                { assert workflow.out.per_sample_mqc_bundle[0][1].size() == 4 },
                { assert snapshot(
                    workflow.out.bam.collect{meta, bam_ ->  file(bam_).name + ':readsMD5,' + bam(bam_).getReadsMD5()},
                    path(workflow.out.index[0][1]),
                    path(workflow.out.flagstat[0][1]),
                    path(workflow.out.idxstats[0][1]),
                    path(workflow.out.stats[0][1])
                ).match() }
            )
        }
    }

    test("homo_sapiens - cram") {

        when {
            workflow {
                """
                input[0] = Channel.of([
                    [ id:'test' ], // meta map
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/illumina/cram/test.paired_end.sorted.cram', checkIfExists: true)
                ])
                input[1] = Channel.of([
                    [ id:'genome' ],
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/genome/genome.fasta', checkIfExists: true),
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/genome/genome.fasta.fai', checkIfExists: true)
                ])
                """
            }
        }

        then {
            def fasta = 'https://raw.githubusercontent.com/nf-core/test-datasets/modules/data/genomics/homo_sapiens/genome/genome.fasta'
            assertAll(
                { assert workflow.success},
                { assert path(workflow.out.metrics.get(0).get(1)).getText().contains("0.999986") },
                { assert workflow.out.per_sample_mqc_bundle.size() == 1 },
                { assert workflow.out.per_sample_mqc_bundle[0][0] == [ id:'test' ] },
                { assert workflow.out.per_sample_mqc_bundle[0][1].size() == 4 },
                { assert snapshot(
                    workflow.out.cram.collect{meta, cram_ ->  file(cram_).name + ':readsMD5,' + cram(cram_, fasta).getReadsMD5()},
                    path(workflow.out.index[0][1]),
                    path(workflow.out.flagstat[0][1]),
                    path(workflow.out.idxstats[0][1]),
                    path(workflow.out.stats[0][1])
                ).match() }
            )
        }
    }

    test("sarscov2 - bam - stub") {

        options "-stub"

        when {
            workflow {
                """
                input[0] = Channel.of([
                    [ id:'test', single_end: false ], // meta map
                    file(params.modules_testdata_base_path + 'genomics/sarscov2/illumina/bam/test.paired_end.sorted.bam', checkIfExists: true)
                ])
                input[1] = Channel.of([
                    [ id:'genome' ],
                    file(params.modules_testdata_base_path + 'genomics/sarscov2/genome/genome.fasta', checkIfExists: true),
                    file(params.modules_testdata_base_path + 'genomics/sarscov2/genome/genome.fasta.fai', checkIfExists: true)
                ])
                """
            }
        }

        then {
            assertAll(
                { assert workflow.success},
                { assert snapshot(workflow.out).match() }
            )
        }
    }

    test("homo_sapiens - cram - stub") {

        options "-stub"

        when {
            workflow {
                """
                input[0] = Channel.of([
                    [ id:'test' ], // meta map
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/illumina/cram/test.paired_end.sorted.cram', checkIfExists: true)
                ])
                input[1] = Channel.of([
                    [ id:'genome' ],
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/genome/genome.fasta', checkIfExists: true),
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/genome/genome.fasta.fai', checkIfExists: true)
                ])
                """
            }
        }

        then {
            assertAll(
                { assert workflow.success},
                { assert snapshot(workflow.out).match() }
            )
        }
    }
}

